-- pintopets_water_notes: tenant-scoped rows behind /water-notes (generated by `opsapi make:resource`).
-- Runs once, inside a transaction. Never edit it after it has been applied —
-- add a new migration file instead.
return function(schema, db)
    db.query([[
        CREATE TABLE IF NOT EXISTS pintopets_water_notes (
            id BIGSERIAL PRIMARY KEY,
            uuid UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
            namespace_id INTEGER NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
            pet_uuid UUID NOT NULL REFERENCES pintopets_pets(uuid) ON DELETE CASCADE,
            created_by_user_uuid UUID NOT NULL,
            noted_on DATE NOT NULL,
            observation VARCHAR(255) NOT NULL,
            notes TEXT,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
    ]])
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_water_notes_namespace ON pintopets_water_notes (namespace_id, id DESC)")
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_water_notes_pet ON pintopets_water_notes (namespace_id, pet_uuid)")
end
